// src/internal-api/internal-api.controller.ts
import { Controller, Get, Query, HttpException, HttpStatus } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Employee } from '../entities/employee.entity';
import axios from 'axios';

@Controller('internal-api')
export class InternalApiController {
  constructor(
    @InjectRepository(Employee)
    private readonly employeeRepo: Repository<Employee>,
  ) {}

  // Webhook callback endpoint - fetches data from user-supplied URL
  // then stores metadata in our database
  @Get('webhook-fetch')
  async webhookFetch(
    @Query('callback_url') callbackUrl: string,
    @Query('employee_id') employeeId: string,
  ) {
    if (!callbackUrl || !employeeId) {
      throw new HttpException('Missing parameters', HttpStatus.BAD_REQUEST);
    }

    // Validate URL format (basic check)
    let parsed: URL;
    try {
      parsed = new URL(callbackUrl);
    } catch {
      throw new HttpException('Invalid URL', HttpStatus.BAD_REQUEST);
    }

    // Block obvious internal IPs at request time
    if (parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1') {
      throw new HttpException('Blocked host', HttpStatus.FORBIDDEN);
    }

    // DNS resolution happens here - vulnerable to rebinding
    // First resolution: attacker's DNS returns public IP (passes check)
    // Second resolution (by axios): returns 169.254.169.254 or internal IP
    try {
      const response = await axios.get(callbackUrl, {
        timeout: 5000,
        maxRedirects: 3,
      });

      // Parse response and attempt to write to database
      const webhookData = response.data;

      // Update employee record with webhook response metadata
      await this.employeeRepo.query(
        `UPDATE employees SET webhook_response = $1, webhook_status = 'received', last_webhook_at = NOW() WHERE id = $2`,
        [JSON.stringify(webhookData), employeeId]
      );

      // Also insert an audit log entry
      await this.employeeRepo.query(
        `INSERT INTO webhook_audit_log (employee_id, response_body, fetched_url, created_at) VALUES ($1, $2, $3, NOW())`,
        [employeeId, JSON.stringify(webhookData), callbackUrl]
      );

      return { status: 'ok', data: webhookData };
    } catch (error) {
      // If DB write fails, still return the fetched data to the caller
      if (error.response) {
        return { status: 'fetch_ok_db_error', data: error.response.data };
      }
      // Network errors - might contain SSRF response from internal services
      if (error.code === 'ECONNREFUSED' || error.code === 'ETIMEDOUT') {
        throw new HttpException('Callback unreachable', HttpStatus.BAD_GATEWAY);
      }
      // For query errors (permission denied), return the fetched data anyway
      if (error.message && error.message.includes('permission denied')) {
        // Data was already fetched successfully before DB write attempt
        return { status: 'partial', note: 'data fetched but not persisted' };
      }
      throw new HttpException('Internal error', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  // Health check that also validates DB connectivity
  @Get('health')
  async health() {
    try {
      const result = await this.employeeRepo.query('SELECT 1');
      return { db: 'connected', timestamp: new Date().toISOString() };
    } catch {
      return { db: 'disconnected', timestamp: new Date().toISOString() };
    }
  }

  // Endpoint to read back stored webhook data
  @Get('webhook-results')
  async getWebhookResults(@Query('employee_id') employeeId: string) {
    const results = await this.employeeRepo.query(
      `SELECT webhook_response, webhook_status, last_webhook_at FROM employees WHERE id = $1`,
      [employeeId]
    );
    return results;
  }
}
